668	
669	Result PrinterConversation::request_credential(const json& arguments, const std::string& action_id)
670	{
671	    m_credential_action    = action_id;
672	    m_credential_arguments = arguments;
673	    m_host.session_changed();
674	    return ok(json{{"state", "credential_requested"},
675	                   {"message", "The app is waiting for the person to enter the printer credential locally."}});
676	}
677	
678	void PrinterConversation::connect(const json& arguments, const std::string& credential)
679	{
680	    const std::string name   = arguments.at("printerName");
681	    const std::string target = arguments.at("target");
682	    const std::string problem =
683	        arguments.at("provider") == "bambu" ?
684	            m_backend.connect_printer(name, arguments.at("deviceId"), credential) :
685	            m_backend.connect_host(name, arguments.at("hostType"), arguments.at("address"), credential);
686	    if (!problem.empty()) {
687	        m_host.post_note("Connection to " + target + " failed: " + problem);
688	        m_host.session_changed();
689	        m_host.start_turn();
690	        return;
691	    }
692	    m_connecting = name;
693	    m_last_look  = {};
694	    m_host.session_changed();
695	}
696	
697	void PrinterConversation::abandon_connection()
698	{
699	    if (m_connecting.empty())
700	        return;
701	    m_backend.cancel_connection(m_connecting);
702	    m_connecting.clear();
703	}
704	
705	void PrinterConversation::tick(std::chrono::steady_clock::time_point now)
706	{
707	    if (m_form && m_form->reading.valid() && m_form->reading.wait_for(std::chrono::seconds(0)) == std::future_status::ready) {
708	        m_form->options = m_form->reading.get();
709	        m_host.session_changed();
710	    }
711	    watch_search(now);
712	    if (m_connecting.empty() || now - m_last_look < kConnectionLook)
713	        return;
714	    m_last_look = now;
715	    const PrinterConnectionInfo info = m_backend.connection(m_connecting);
716	    if (info.state == "connecting")
717	        return;
718	    const std::string name = m_connecting;
719	    m_connecting.clear();
720	    m_host.post_note(info.state == "verified" ? "Connection to " + name + " verified." :
721	                                                "Connection to " + name + " failed: " + info.message);
722	    m_host.printers_changed();
723	    m_host.session_changed();
724	    m_host.start_turn();
725	}
726	
727	void PrinterConversation::watch_search(std::chrono::steady_clock::time_point now)
728	{
729	    // An attempt under way is read by tick alone: reading a connection can
730	    // settle it.
731	    if (!m_search || m_search->found || !m_connecting.empty() ||
732	        now - m_search->last_look < (m_search->said_none || m_search->port != DiscoveryPort::Ours ? std::chrono::seconds(kSearchLateLook) :
733	                                                                                                       std::chrono::seconds(kConnectionLook)))
734	        return;
735	    m_search->last_look = now;
736	    const PrinterConnectionInfo info = m_backend.connection(m_prepared);
737	    // The printer was renamed or removed, or nothing can reach the network now.
738	    if (info.provider != "bambu" || info.state == "unavailable") {
739	        m_search.reset();
740	        return;
741	    }
742	    if (info.state == "verified") {
743	        m_search->found = true;
744	        return;
745	    }
746	    std::string note;
747	    if (found_on_network(info)) {
748	        m_search->found = true;
749	        bool in_cloud_mode = false;
750	        for (const ConnectionCandidate& candidate : info.candidates) {
751	            if (candidate.account_only)
752	                continue;
753	            in_cloud_mode = in_cloud_mode || !candidate.lan_mode;
754	            note += (note.empty() ? "The network search found " : "; ") + with_address(candidate) +
755	                    (candidate.lan_mode ? " in LAN mode, which can be connected" : " with LAN Only off, which cannot be connected as it is");
756	        }
757	        note += ".";
758	        if (in_cloud_mode)
759	            note += std::string(" ") + kPersonsChoice;
760	    } else if (now - m_search->started < kSearchWait)
761	        return;
762	    else {
763	        // Checked only once discovery has had time to bind: the check itself
764	        // binds the port for a moment, which could cost discovery its own bind.
765	        const DiscoveryPort port = m_backend.discovery_port();
766	        if (port == m_search->port && (port != DiscoveryPort::Ours || m_search->said_none))
767	            return;
768	        m_search->port = port;
769	        if (port == DiscoveryPort::Taken)
770	            note = kPortTaken;
771	        else if (port == DiscoveryPort::Free)
772	            note = kNotListening;
