        network_check_call("printer_connect", {{"deviceId", "P1s"}}, "finding3_connect_by_name");
        std::cerr << "HARNESS NETWORK finding 3: heard all along: " << devices->get_local_machinelist().size() << " printer(s) in the local list\n";
        panel->close();
        wait_for([panel] { return !panel->IsShown(); }, 5s);

        // Finding 1: one attempt with a deliberately wrong code.
