            }, 60s);
            check(ended, "finding1_a_note_says_how_it_ended");
            code_state("after the attempt");
            wait_for([&] { notes(); return false; }, 5s);
            network_check_call("printer_connection_status", nlohmann::json::object(), "finding1_later_read");
        }
        closer->Stop();
        notes();
        panel->close();
        finish();
    }

