    ModelObject* current_model_object = new_model.objects[obj_idx];

    wxBusyCursor wait;
    ModelObjectPtrs new_objects;
    current_model_object->split(&new_objects, wxGetApp().app_config->get_bool("keep_painting"));
    if (new_objects.size() == 1)
