596	std::string OrcaPrinterBackend::keep_connection_report(const std::string& text)
597	{
598	    const std::filesystem::path folder = std::filesystem::u8path(Slic3r::data_dir()) / "jusprin" / "connection_reports";
599	    std::error_code             failed;
600	    std::filesystem::create_directories(folder, failed);
601	    const auto seconds = std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count();
602	    const std::filesystem::path path = folder / ("report-" + std::to_string(seconds) + ".json");
603	    std::ofstream               file(path, std::ios::binary);
604	    file << text;
605	    file.close();
606	    return file.good() ? path.u8string() : std::string();
607	}
